def solution(s: str) -> str:
    n, m = map(int, s.strip().split())
    if n > m:
        n, m = m, n
    if n == 1:
        return str(m if m % 2 == 0 else m - 1) if m >= 3 else "0"
    if n == 2 and m == 2:
        return "0"
    if n == 2:
        return str(m // 3 * 2 + (2 if m % 3 else 0) if m >= 3 else 0)
    if n == 3:
        return str(m * 2 if m % 2 == 0 else m * 2 - 1)
    if n >= 4:
        return str(((n - 1) * m) * 2 // 3 * 1.5)  # fallback heuristic
    return "0"

