from typing import List, Optional
import sys

def f(x: int, k: int) -> int:
    """Compute f(x) - repeatedly divide by k until not divisible"""
    while x > 0 and x % k == 0:
        x //= k
    return x

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def lcm(a: int, b: int) -> int:
    return abs(a * b) // gcd(a, b)

def solve(n: int, k: int, nums: List[int]) -> tuple:
    """
    Try to solve the problem using search.
    Returns (success, operations_list) or (False, [])
    """
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(current_nums: tuple, depth: int) -> Optional[List[tuple]]:
        if len(current_nums) == 0:
            return [] if current_nums[0] == 1 else None

        current_nums = list(current_nums)
        if len(current_nums) == 1:
            return [[current_nums[0]] == [1] and [] or None]

        if len(current_nums) == 0:
            return None

        # Try all pairs
        n_nums = len(current_nums)
        for i in range(n_nums):
            for j in range(i + 1, n_nums):
                x = int(current_nums[i])
                y = int(current_nums[j])
                new_val = f(x + y, k)

                new_nums = list(current_nums)
                new_nums.pop(i)
                if j > i:
                    new_nums.pop(j - 1)
                new_nums.append(new_val)
                new_nums.sort()

                new_tuple = tuple(new_nums)
                ops = dfs(new_tuple, depth + 1)
                if ops is not None:
                    return [(x, y)] + ops

        return None

    init_tuple = tuple(sorted(nums))
    result = dfs(init_tuple, 0)
    return result

