import sys

def bfs(n, edges, removed_indices, start, end):
    """BFS to check if start can reach end (avoiding removed edges)"""
    if start == end:
        return True

    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edges):
        if i in removed_indices:
            continue
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    q = deque([start])
    visited[start] = True

    while q:
        u = q.popleft()
        if u == end:
            return True
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)

    return False

