        for i in range(n):
            for j in range(m):
                d = directions[i][j]
                if d == 'U': nxt[i][j] = (i-1, j)
                elif d == 'R': nxt[i][j] = (i, j+1)
                elif d == 'D': nxt[i][j] = (i+1, j)
                elif d == 'L': nxt[i][j] = (i, j-1)

        visited = [[False]*m for _ in range(n)]
        cycle_size = 0

        for i in range(n):
            for j in range(m):
                if not visited[i][j]:
                    # Trace path to find cycle
                    path = []
                    cur = (i, j)
                    while not visited[cur[0]][cur[1]]:
                        visited[cur[0]][cur[1]] = True
                        path.append(cur)
                        cur = nxt[cur[0]][cur[1]]

                    # Check if cur is in current cycle (in path)
                    if cur in path:
                        idx_in_path = path.index(cur)
                        cycle_len = len(path) - idx_in_path
                        cycle_size += cycle_len
                    else:
                        # Cur was visited in previous component
                        pass

        # Recalculate for disjoints
        visited = [[False]*m for _ in range(n)]
        components = set()

        for i in range(n):
            for j in range(m):
                if not visited[i][j]:
                    path = []
                    cur = (i, j)
                    while not visited[cur[0]][cur[1]]:
                        visited[cur[0]][cur[1]] = True
                        path.append(cur)
                        cur = nxt[cur[0]][cur[1]]

                    # Find cycle portion
                    if cur in path:
                        cycle_start = path.index(cur)
                        cycle_cells = tuple(sorted(path[cycle_start:]))
                        components.add(cycle_cells)

        max_robots = 0
        max_black = 0

        for comp in components:
            size = len(comp)
            max_robots += size
            black = sum(1 for (r, c) in comp if colors[(r, c)] == '0')
            max_black += black

        output.append(f"{max_robots} {max_black}")

