    """Pollard's rho algorithm to find a non-trivial factor"""
    if n % 2 == 0:
        return 2
    x = 2
    y = 2
    d = 1
    c = 1

    while d == 1:
        x = (x * x + c) % n
        y = (y * y + c) % n
        y = (y * y + c) % n
        d = gcd(abs(x - y), n)

    return d if d != n else None

