    return result


def power(base, exp):
    """Compute base^exp mod MOD, handling negative exponents."""
    if exp >= 0:
        return pow(base, exp, MOD)
    else:
        # Compute modular inverse for negative exponent
        num = pow(base, abs(exp), MOD)
        return pow(num, MOD - 2, MOD)  # Fermat's little theorem


def count_spanning_with_forest(n, edge_list):
    """
    Count spanning trees containing forest on n vertices
    with given edge_list (already checked to be a forest).
    Formula: n^{c-2} * product of component sizes
    """
    global MOD

    # Build UF to find components
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    for u, v in edge_list:
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_u] = root_v

    # Group vertices by component root
    comp = {}
    for i in range(n):
        r = find(i)
        if r not in comp:
            comp[r] = 0
        comp[r] += 1

    c = len(comp)
    sizes = list(comp.values())

    if c == 0:
        return 0

    prod = product_sizes(sizes)

    if c == 1:
        # n^{1-2} * s = n^{-1} * n = 1
        return 1
    elif c == n:
        # n^{n-2} * 1 = n^{n-2}
        return power(n, n - 2)
    else:
        # n^{c-2} * prod
        return (prod * power(n, c - 2)) % MOD


