def solution(s):
    import math

    x, y = map(int, s.strip().split())

    def solve(a, b):
        if b == 0:
            return 0

        g = math.gcd(a, b)
        if g == 0:
            return 0

        if g == a:
            return 1

        a_prime = a // g
        b_prime = b // g

        # Find smallest prime factor of a_prime
        if a_prime == 1:
            return b_prime

        p = None
        for i in range(2, int(math.isqrt(a_prime)) + 1):
            if a_prime % i == 0:
                p = i
                break
        if p is None:
            p = a_prime

        # Compute steps efficiently
        # When working with reduced b', we need to reach a point where 
        # gcd(a', b'-k) increases (shares a factor with a')
        # The smallest such factor is p (smallest prime dividing a')

        remainder = b_prime % p
        if remainder == 0:
            # Already at jump point
            return b_prime // p
        else:
            # Need remainder steps to reach jump point
            return remainder + solve(a, b - g * remainder)

    return str(solve(x, y)) + '\n'

