class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        fwd = [v, cap, len(self.graph[v])]
        bwd = [u, 0, len(self.graph[u])]
        self.graph[u].append(fwd)
        self.graph[v].append(bwd)

    def bfs(self, s, t):
        self.dist = [-1] * self.n
        self.dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v, cap, rev in self.graph[u]:
                if cap > 0 and self.dist[v] == -1:
                    self.dist[v] = self.dist[u] + 1
                    q.append(v)
        return self.dist[t] != -1

    def dfs(self, u, t, pushed, ptr):
        if pushed == 0 or u == t:
            return pushed
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.dist[v] == self.dist[u] + 1 and cap > 0:
                tr = self.dfs(v, t, min(pushed, cap), ptr)
                if tr == 0:
                    continue
                self.graph[u][i][1] -= tr
                self.graph[v][rev][1] += tr
                return tr
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

