        elif k == 2:
            a, b = lits[0], lits[1]
            x, y = abs(a), abs(b)
            var_appears[x] = True
            var_appears[y] = True

            # Edge between x and y (constraint on the pair)
            adj[x].append(y)
            adj[y].append(x)

    # Count variables not appearing anywhere
