    base_ans = pow(2, not_in_clause_count, MOD)

    # Find connected components and compute constraints for each
    seen = [False] * (m + 1)
    total_ans = base_ans

    for start in range(1, m + 1):
        if seen[start] or not var_appears[start] or len(adj[start]) == 0:
            continue

        # BFS to find component
        comp = []
        queue = deque([start])
        seen[start] = True

        while queue:
            v = queue.popleft()
            comp.append(v)

            for neighbor in adj[v]:
