MOD = 1000000007

def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    F = int(parts[0])
    B = int(parts[1])
    N = int(parts[2])

    p = list(map(int, lines[1].split()))
    c = list(map(int, lines[2].split()))

    # Handle edge case
    if N <= 0:
        return "0\n"

    # Compute box compositions using DP
    # G(x) = 1/(1 - (x^c1 + ... + x^cB))
    memo_box = {}

    def count_box(s):
        if s == 0:
            return 1
        if s in memo_box:
            return memo_box[s]

        dp = [0] * (s + 1)
        dp[0] = 1
        for choco in c:
            for i in range(choco, s + 1):
                dp[i] = (dp[i] + dp[i - choco]) % MOD

        memo_box[s] = dp[s]
        return dp[s]

    # For flowers, need matrix exponentiation conceptually
    # But given constraints, use DP with limited range for practical computation

    MAX_S = 3000  # Reasonable limit for computation
    memo_flower = {}

    def count_flower_flower(n_flowers, remaining_s):
        if (n_flowers, remaining_s) in memo_flower:
            return memo_flower[(n_flowers, remaining_s)]

        if n_flowers == 0:
            return 1 if remaining_s == 0 else 0

        res = 0
        for petal in p:
            if remaining_s >= petal:
                res = (res + count_flower_flower(n_flowers - 1, remaining_s - petal)) % MOD

        memo_flower[(n_flowers, remaining_s)] = res
        return res

    count_flower_flower(N, 0)

    ans = 0
    for s in range(MAX_S):
        f_ways = count_flower_flower(N, s)
        b_ways = count_box(s)
        ans = (ans + f_ways * b_ways) % MOD

    # Attempt larger sums if needed
    for s in range(MAX_S, MAX_S + 200):
        f_ways = count_flower_flower(N, s)
        if f_ways == 0:
            break
        b_ways = count_box(s)
        ans = (ans + f_ways * b_ways) % MOD

    return f"{ans}\n"

